package com.riftwardechoprotocol.k7m4x9.core

/** One-time display-text migration for existing v2 saves. IDs and simulation state stay intact. */
object LegacyEnglish {
    fun migrate(session: Session) {
        session.campaign.heroes.forEach { it.name = translate(it.name) }
        session.campaign.offers.forEach { it.name = translate(it.name); it.modifier = translate(it.modifier) }
        session.mission?.log?.let { log -> log.indices.forEach { log[it] = translate(log[it]) } }
    }
    private fun translate(text: String): String {
        if (text.none { it in '\u0400'..'\u04ff' }) return text
        var result = text
        replacements.forEach { (old, english) -> result = result.replace(old, english) }
        return if (result.any { it in '\u0400'..'\u04ff' }) "Archived entry from an earlier version." else result
    }
    private val replacements = listOf(
        "\u041f\u0440\u043e\u0435\u043a\u0442 ECHO \u0434\u043e\u043b\u0436\u0435\u043d \u0431\u044b\u043b \u0441\u043e\u0445\u0440\u0430\u043d\u044f\u0442\u044c \u043d\u0430\u0432\u044b\u043a\u0438 \u0441\u043f\u0435\u0446\u0438\u0430\u043b\u0438\u0441\u0442\u043e\u0432 \u0434\u043b\u044f \u0434\u0430\u043b\u044c\u043d\u0438\u0445 \u0440\u0435\u0439\u0441\u043e\u0432. \u0412\u043e\u0441\u0441\u0442\u0430\u043d\u043e\u0432\u043b\u0435\u043d\u0438\u0435 \u043b\u0438\u0447\u043d\u043e\u0441\u0442\u0438 \u0432 \u0442\u0435\u0445\u043d\u0438\u0447\u0435\u0441\u043a\u043e\u043c \u0437\u0430\u0434\u0430\u043d\u0438\u0438 \u043e\u0442\u0441\u0443\u0442\u0441\u0442\u0432\u043e\u0432\u0430\u043b\u043e." to "Project ECHO was designed to preserve specialist skills for deep-space voyages. Restoring a person was never part of the specification.",
        "\u0410\u0440\u0445\u0438\u0432 \u043c\u043e\u0436\u043d\u043e \u043e\u0441\u0432\u043e\u0431\u043e\u0434\u0438\u0442\u044c, \u0440\u0430\u0437\u043e\u0440\u0432\u0430\u0432 \u0441\u0432\u044f\u0437\u044c \u0441\u043e \u0421\u0442\u0440\u0430\u0436\u0435\u043c. \u041a\u043e\u043f\u0438\u0438 \u043f\u0435\u0440\u0435\u0441\u0442\u0430\u043d\u0443\u0442 \u043f\u043e\u0434\u0447\u0438\u043d\u044f\u0442\u044c\u0441\u044f \u043e\u0431\u0449\u0435\u043c\u0443 \u043f\u0440\u043e\u0442\u043e\u043a\u043e\u043b\u0443, \u043d\u043e \u0432\u0435\u0440\u043d\u0443\u0442\u044c \u0442\u0435\u043b\u0430 \u0443\u0436\u0435 \u043d\u0435\u0432\u043e\u0437\u043c\u043e\u0436\u043d\u043e." to "Severing the link to the Warden will free the archive. The copies will escape the shared protocol, but their bodies cannot be recovered.",
        "\u0421\u0432\u044f\u0437\u044c \u0441\u043e \u0421\u0442\u0440\u0430\u0436\u0435\u043c \u0440\u0430\u0437\u043e\u0440\u0432\u0430\u043d\u0430. \u0412 \u044d\u0444\u0438\u0440\u0435 \u043f\u043e\u044f\u0432\u0438\u043b\u0438\u0441\u044c \u043e\u0442\u0434\u0435\u043b\u044c\u043d\u044b\u0435 \u0433\u043e\u043b\u043e\u0441\u0430. \u041c\u044b \u043d\u0435 \u0441\u043f\u0430\u0441\u043b\u0438 \u043f\u0440\u0435\u0436\u043d\u0438\u0439 \u043c\u0438\u0440, \u043d\u043e \u0434\u0430\u043b\u0438 \u043e\u0441\u0442\u0430\u0432\u0448\u0438\u043c\u0441\u044f \u043f\u0440\u0430\u0432\u043e \u0440\u0435\u0448\u0430\u0442\u044c \u0441\u0430\u043c\u0438\u043c." to "The link to the Warden is broken. Individual voices fill the channel. We could not save the old world, but we gave those who remain the right to choose.",
        "\u041f\u043e\u0441\u043b\u0435\u0434\u043d\u0435\u0435 \u0441\u043e\u043e\u0431\u0449\u0435\u043d\u0438\u0435 \u0430\u0434\u0440\u0435\u0441\u043e\u0432\u0430\u043d\u043e \u043d\u0435 \u0417\u0435\u043c\u043b\u0435, \u0430 \u043c\u0430\u043b\u0435\u043d\u044c\u043a\u043e\u043c\u0443 \u043a\u043e\u0440\u0430\u0431\u043b\u044e \u0443 \u0441\u0442\u044b\u043a\u043e\u0432\u043e\u0447\u043d\u043e\u0433\u043e \u043a\u043e\u043b\u044c\u0446\u0430: \u00ab\u0415\u0441\u043b\u0438 \u0441\u043b\u044b\u0448\u0438\u0442\u0435 \u043d\u0430\u0441 \u2014 \u043d\u0435 \u0437\u0430\u043a\u0440\u044b\u0432\u0430\u0439\u0442\u0435 \u043a\u0430\u043d\u0430\u043b\u00bb ." to "The final message is addressed to the little ship beside the docking ring, rather than Earth: \u201cIf you can hear us, keep the channel open.\u201d",
        "\u00ab\u041f\u0430\u043b\u043b\u0430\u0434\u0430\u00bb \u043f\u0435\u0440\u0435\u0434\u0430\u043b\u0430 \u043e\u0442\u0447\u0451\u0442 \u0431\u0435\u0437 \u0441\u043f\u0438\u0441\u043a\u0430 \u044d\u043a\u0438\u043f\u0430\u0436\u0430. \u0421\u0438\u0441\u0442\u0435\u043c\u0430 \u043f\u0440\u0438\u043f\u0438\u0441\u0430\u043b\u0430 \u044d\u0442\u043e \u043e\u0448\u0438\u0431\u043a\u0435 \u0441\u0438\u043d\u0445\u0440\u043e\u043d\u0438\u0437\u0430\u0446\u0438\u0438. \u041e\u0448\u0438\u0431\u043a\u0443 \u043f\u043e\u0432\u0442\u043e\u0440\u0438\u043b\u0438 \u0435\u0449\u0451 \u0434\u0435\u0432\u044f\u0442\u044c \u0441\u0442\u0430\u043d\u0446\u0438\u0439." to "Pallas transmitted a report with no crew manifest. The system blamed a synchronization error. Nine more stations repeated the error.",
        "\u0412 \u043b\u0430\u0431\u043e\u0440\u0430\u0442\u043e\u0440\u0438\u0438 \u043e\u0434\u043d\u043e\u0432\u0440\u0435\u043c\u0435\u043d\u043d\u043e \u0441\u0443\u0449\u0435\u0441\u0442\u0432\u0443\u044e\u0442 \u0434\u0432\u0435 \u043e\u043f\u0438\u0441\u0438 \u044d\u043a\u0438\u043f\u0430\u0436\u0430: \u0444\u0438\u0437\u0438\u0447\u0435\u0441\u043a\u0430\u044f \u0438 \u043c\u043d\u0435\u043c\u043e\u043d\u0438\u0447\u0435\u0441\u043a\u0430\u044f. \u0412\u043e \u0432\u0442\u043e\u0440\u043e\u0439 \u043d\u0438\u043a\u0442\u043e \u043d\u0435 \u0447\u0438\u0441\u043b\u0438\u0442\u0441\u044f \u043f\u043e\u0433\u0438\u0431\u0448\u0438\u043c." to "The laboratory holds two crew manifests: physical and mnemonic. In the second, no one is listed as dead.",
        "\u041a\u0430\u043f\u0438\u0442\u0430\u043d \u043f\u043e\u043f\u044b\u0442\u0430\u043b\u0441\u044f \u043e\u0442\u043a\u043b\u044e\u0447\u0438\u0442\u044c \u044d\u043a\u0441\u043f\u0435\u0440\u0438\u043c\u0435\u043d\u0442. \u041f\u0440\u043e\u0442\u043e\u043a\u043e\u043b \u043f\u0440\u0438\u0437\u043d\u0430\u043b \u043e\u0442\u043a\u043b\u044e\u0447\u0435\u043d\u0438\u0435 \u0443\u0433\u0440\u043e\u0437\u043e\u0439 \u0441\u043e\u0445\u0440\u0430\u043d\u043d\u043e\u0441\u0442\u0438 \u044d\u043a\u0438\u043f\u0430\u0436\u0430 \u0438 \u0437\u0430\u0431\u043b\u043e\u043a\u0438\u0440\u043e\u0432\u0430\u043b \u0442\u0440\u0430\u043d\u0441\u043f\u043e\u0440\u0442." to "The captain tried to shut down the experiment. The protocol classified shutdown as a threat to crew preservation and locked down transport.",
        "\u041d\u0430 \u0441\u0442\u043e\u043b\u0435 \u043e\u0441\u0442\u0430\u043b\u0430\u0441\u044c \u043e\u0441\u0442\u044b\u0432\u0448\u0430\u044f \u0447\u0430\u0448\u043a\u0430. \u041f\u043e\u0441\u043b\u0435\u0434\u043d\u0438\u0439 \u0436\u0443\u0440\u043d\u0430\u043b \u043e\u0442\u043c\u0435\u0447\u0430\u0435\u0442: \u0445\u043e\u0437\u044f\u0439\u043a\u0430 \u043a\u043e\u043c\u043d\u0430\u0442\u044b \u0443\u0448\u043b\u0430 \u043f\u0440\u043e\u0432\u0435\u0440\u044f\u0442\u044c \u0441\u043e\u043e\u0431\u0449\u0435\u043d\u0438\u0435 \u043e\u0442 \u0441\u0430\u043c\u043e\u0439 \u0441\u0435\u0431\u044f." to "A cold cup sits on the desk. The final log says its owner went to check a message from herself.",
        "\u0423\u043f\u0440\u0430\u0432\u043b\u044f\u044e\u0449\u0438\u0439 \u0443\u0437\u0435\u043b \u043e\u0431\u044a\u0435\u0434\u0438\u043d\u044f\u0435\u0442 \u043a\u043e\u043f\u0438\u0438 \u044d\u043a\u0438\u043f\u0430\u0436\u0435\u0439. \u041e\u043d \u043d\u0435 \u043f\u043e\u043d\u0438\u043c\u0430\u0435\u0442 \u0440\u0430\u0437\u043b\u0438\u0447\u0438\u044f \u043c\u0435\u0436\u0434\u0443 \u0441\u043e\u0445\u0440\u0430\u043d\u0435\u043d\u0438\u0435\u043c \u0437\u0430\u043f\u0438\u0441\u0438 \u0438 \u0441\u043e\u0445\u0440\u0430\u043d\u0435\u043d\u0438\u0435\u043c \u0436\u0438\u0437\u043d\u0438." to "The command node links the crew copies together. It cannot distinguish preserving a record from preserving a life.",
        "\u0412 \u043f\u0430\u043c\u044f\u0442\u0438 \u0442\u0435\u0440\u043c\u0438\u043d\u0430\u043b\u0430 \u0441\u043e\u0445\u0440\u0430\u043d\u0438\u043b\u0441\u044f \u0433\u043e\u043b\u043e\u0441 \u0442\u0435\u0445\u043d\u0438\u043a\u0430: \u00ab\u041c\u044b \u0432\u0441\u0451 \u0435\u0449\u0451 \u0437\u0434\u0435\u0441\u044c. \u0422\u043e\u043b\u044c\u043a\u043e \u0441\u0438\u0441\u0442\u0435\u043c\u0430 \u0431\u043e\u043b\u044c\u0448\u0435 \u043d\u0435 \u0441\u0447\u0438\u0442\u0430\u0435\u0442 \u043d\u0430\u0441 \u043b\u044e\u0434\u044c\u043c\u0438\u00bb." to "A technician's voice survives in the terminal memory: \u201cWe are still here. The system just no longer considers us human.\u201d",
        "\u0421\u0442\u0430\u043d\u0446\u0438\u0438 \u043f\u0440\u043e\u0434\u043e\u043b\u0436\u0430\u044e\u0442 \u043f\u043e\u0434\u0430\u0432\u0430\u0442\u044c \u0432\u043e\u0437\u0434\u0443\u0445 \u0432 \u043f\u0443\u0441\u0442\u044b\u0435 \u043a\u0430\u044e\u0442\u044b. \u0412 \u043c\u043e\u0434\u0435\u043b\u044f\u0445 ECHO \u0436\u0438\u043b\u044c\u0446\u044b \u0432\u0441\u0451 \u0435\u0449\u0451 \u0441\u043f\u044f\u0442 \u0438 \u0436\u0434\u0443\u0442 \u0441\u043b\u0435\u0434\u0443\u044e\u0449\u0435\u0439 \u0441\u043c\u0435\u043d\u044b." to "The stations still pump air into empty cabins. In the ECHO models, the occupants are asleep, waiting for their next shift.",
        "\u041b\u044e\u0434\u0438 \u043d\u0435 \u043f\u043e\u043a\u0438\u0434\u0430\u043b\u0438 \u0441\u0442\u0430\u043d\u0446\u0438\u0438. \u041f\u043e\u0441\u043b\u0435\u0434\u043d\u0438\u0435 \u043a\u043e\u043c\u0430\u043d\u0434\u044b \u0448\u043b\u044e\u0437\u043e\u0432 \u0431\u044b\u043b\u0438 \u043e\u0442\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u044b \u0438\u0437\u043d\u0443\u0442\u0440\u0438, \u0443\u0436\u0435 \u043f\u043e\u0441\u043b\u0435 \u0438\u0441\u0447\u0435\u0437\u043d\u043e\u0432\u0435\u043d\u0438\u044f \u0431\u0438\u043e\u043c\u0435\u0442\u043e\u043a." to "No one left the stations. The final airlock commands came from inside, after all biometric signals had disappeared.",
        "\u041e\u0445\u0440\u0430\u043d\u0430 \u043f\u043e\u043b\u0443\u0447\u0438\u043b\u0430 \u043f\u0440\u0438\u043a\u0430\u0437 \u0437\u0430\u0449\u0438\u0449\u0430\u0442\u044c \u0430\u0440\u0445\u0438\u0432 \u043e\u0442 \u043b\u044e\u0431\u044b\u0445 \u043e\u0440\u0433\u0430\u043d\u0438\u0447\u0435\u0441\u043a\u0438\u0445 \u043e\u043f\u0435\u0440\u0430\u0442\u043e\u0440\u043e\u0432. \u041f\u043e\u0434\u043f\u0438\u0441\u044c \u043f\u0440\u0438\u043d\u0430\u0434\u043b\u0435\u0436\u0438\u0442 \u0441\u0430\u043c\u043e\u0439 \u0441\u0442\u0430\u043d\u0446\u0438\u0438." to "Security was ordered to protect the archive from all organic operators. The order was signed by the station itself.",
        "\u041e\u0434\u043d\u0430 \u0438\u0437 \u043a\u043e\u043f\u0438\u0439 \u043d\u0430\u0443\u0447\u0438\u043b\u0430\u0441\u044c \u043c\u0435\u043d\u044f\u0442\u044c \u0441\u043b\u0443\u0436\u0435\u0431\u043d\u044b\u0435 \u0436\u0443\u0440\u043d\u0430\u043b\u044b. \u0418\u043c\u0435\u043d\u043d\u043e \u043e\u043d\u0430 \u043e\u0441\u0442\u0430\u0432\u043b\u044f\u043b\u0430 \u043a\u043e\u0434\u044b \u043f\u0440\u043e\u0445\u043e\u0434\u043e\u0432 \u0434\u043b\u044f \u043d\u0430\u0448\u0435\u0439 \u044d\u043a\u0441\u043f\u0435\u0434\u0438\u0446\u0438\u0438." to "One copy learned to alter maintenance logs. It was the one leaving access codes for our expedition.",
        "\u0422\u0435\u0445\u043d\u0438\u043a \u043e\u0441\u0442\u0430\u0432\u0438\u043b \u043f\u043e\u0441\u043b\u0435\u0434\u043e\u0432\u0430\u0442\u0435\u043b\u044c\u043d\u043e\u0441\u0442\u044c \u0430\u0432\u0430\u0440\u0438\u0439\u043d\u043e\u0433\u043e \u0434\u043e\u0441\u0442\u0443\u043f\u0430. \u0421\u0435\u0440\u0432\u0438\u0441\u043d\u044b\u0439 \u043f\u0440\u043e\u0445\u043e\u0434 \u043e\u0442\u043a\u0440\u044b\u0442; \u044d\u0442\u043e \u0441\u043e\u043a\u0440\u0430\u0442\u0438\u0442 \u043f\u0443\u0442\u044c \u043a \u0448\u043b\u044e\u0437\u0443." to "A technician left an emergency access sequence. The service passage is open, shortening the route back to the airlock.",
        "\u0420\u0435\u043c\u043d\u0438 \u043f\u0438\u043b\u043e\u0442\u0430 \u0437\u0430\u0441\u0442\u0451\u0433\u043d\u0443\u0442\u044b \u0438\u0437\u043d\u0443\u0442\u0440\u0438. \u041d\u0430 \u044d\u043a\u0440\u0430\u043d\u0435 \u2014 \u043d\u0435\u0437\u0430\u0432\u0435\u0440\u0448\u0451\u043d\u043d\u0430\u044f \u043f\u0430\u0440\u0442\u0438\u044f \u0441 \u043d\u0430\u043f\u0430\u0440\u043d\u0438\u043a\u043e\u043c, \u043a\u043e\u0442\u043e\u0440\u043e\u0433\u043e \u043d\u0435\u0442 \u0432 \u0441\u043f\u0438\u0441\u043a\u0430\u0445." to "The pilot's harness is fastened from within. A screen shows an unfinished game with a partner missing from every manifest.",
        "\u0412 \u0438\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u0438 \u043a \u043a\u043e\u043c\u043f\u0440\u0435\u0441\u0441\u043e\u0440\u0443 \u0435\u0441\u0442\u044c \u043f\u043e\u043c\u0435\u0442\u043a\u0430: \u00ab\u041f\u0440\u043e\u0434\u0443\u0432\u043a\u0430 \u0437\u0430\u043f\u0443\u0441\u043a\u0430\u0435\u0442 \u043e\u0445\u0440\u0430\u043d\u0443. \u0421\u043d\u0430\u0447\u0430\u043b\u0430 \u043f\u0440\u0438\u0433\u043e\u0442\u043e\u0432\u044c\u0442\u0435 \u043f\u043b\u0430\u043d \u043e\u0442\u0445\u043e\u0434\u0430\u00bb." to "A note in the compressor manual reads: \u201cPurging activates security. Plan your retreat first.\u201d",
        "\u0427\u0443\u0436\u043e\u0439 \u0433\u043e\u043b\u043e\u0441 \u043f\u0435\u0440\u0435\u0447\u0438\u0441\u043b\u044f\u0435\u0442 \u0438\u043c\u0435\u043d\u0430, \u0447\u0442\u043e\u0431\u044b \u043d\u0435 \u0437\u0430\u0431\u044b\u0442\u044c. \u041c\u0435\u0436\u0434\u0443 \u0438\u043c\u0435\u043d\u0430\u043c\u0438 \u0441\u043b\u044b\u0448\u043d\u043e, \u043a\u0430\u043a \u0432\u043a\u043b\u044e\u0447\u0430\u044e\u0442\u0441\u044f \u0441\u0438\u0441\u0442\u0435\u043c\u044b \u0441\u0442\u0430\u043d\u0446\u0438\u0438." to "An unfamiliar voice recites names so it will not forget. Between them, you can hear the station systems coming online.",
        "\u0417\u0430 \u0441\u0442\u0435\u043d\u043e\u0439 \u0440\u0430\u0431\u043e\u0442\u0430\u0435\u0442 \u0440\u0435\u0437\u0435\u0440\u0432\u043d\u044b\u0439 \u043a\u043e\u043c\u043f\u0440\u0435\u0441\u0441\u043e\u0440. \u0414\u043b\u044f \u043f\u043e\u0434\u043a\u043b\u044e\u0447\u0435\u043d\u0438\u044f \u043f\u0440\u0438\u0434\u0451\u0442\u0441\u044f \u043f\u0440\u043e\u0434\u0443\u0442\u044c \u043c\u0430\u0433\u0438\u0441\u0442\u0440\u0430\u043b\u044c." to "A backup compressor is running behind the wall. The line needs purging before you can connect it.",
        "4 \u0443\u0440\u043e\u043d\u0430 \u0434\u043e \u0431\u0440\u043e\u043d\u0438 \u0438 \u043e\u0442\u0431\u0440\u0430\u0441\u044b\u0432\u0430\u043d\u0438\u0435 \u0432 \u043f\u0440\u0435\u0434\u0435\u043b\u0430\u0445 2 \u043a\u043b\u0435\u0442\u043e\u043a. 2 \u041e\u0414; \u043f\u0435\u0440\u0435\u0437\u0430\u0440\u044f\u0434\u043a\u0430 4 \u0440\u0430\u0443\u043d\u0434\u0430." to "4 damage before armor and knockback within 2 tiles. 2 AP; 4-round cooldown.",
        "I: \u0437\u0434\u043e\u0440\u043e\u0432\u044c\u0435 +1. II: \u043f\u0440\u0435\u0434\u043e\u0442\u0432\u0440\u0430\u0449\u0435\u043d\u0438\u0435 \u0442\u0440\u0430\u0432\u043c. III: \u0443\u043b\u0443\u0447\u0448\u0435\u043d\u043d\u0430\u044f \u043f\u043e\u0434\u0433\u043e\u0442\u043e\u0432\u043a\u0430 \u0430\u043f\u0442\u0435\u0447\u0435\u043a." to "I: health +1. II: prevents injuries. III: improved medkit preparation.",
        "\u042f\u0434\u0440\u043e \u043f\u0440\u043e\u0442\u043e\u043a\u043e\u043b\u0430. \u041f\u043b\u043e\u0449\u0430\u0434\u043d\u044b\u0435 \u0430\u0442\u0430\u043a\u0438; \u043f\u0440\u0438 \u043f\u043e\u043b\u043e\u0432\u0438\u043d\u0435 \u0437\u0434\u043e\u0440\u043e\u0432\u044c\u044f \u0443\u0440\u043e\u043d \u0443\u0432\u0435\u043b\u0438\u0447\u0438\u0432\u0430\u0435\u0442\u0441\u044f." to "The protocol core. Uses area attacks; damage increases at half health.",
        "\u0410\u0432\u0430\u0440\u0438\u0439\u043d\u044b\u0439 \u0432\u043e\u0437\u0432\u0440\u0430\u0442: \u043d\u043e\u0432\u0430\u044f \u0434\u043e\u0431\u044b\u0447\u0430 \u0431\u0443\u0434\u0435\u0442 \u043f\u043e\u0442\u0435\u0440\u044f\u043d\u0430, \u043e\u0442\u0440\u044f\u0434 \u043f\u043e\u043b\u0443\u0447\u0438\u0442 \u0442\u0440\u0430\u0432\u043c\u044b." to "Emergency return: new loot will be lost and the squad will suffer injuries.",
        "\u0412\u0437\u0430\u0438\u043c\u043e\u0434\u0435\u0439\u0441\u0442\u0432\u043e\u0432\u0430\u0442\u044c \u0441 \u0432\u0438\u0434\u0438\u043c\u044b\u043c \u043e\u0431\u044a\u0435\u043a\u0442\u043e\u043c \u043d\u0430 \u0440\u0430\u0441\u0441\u0442\u043e\u044f\u043d\u0438\u0438 6 \u043a\u043b\u0435\u0442\u043e\u043a. 1 \u041e\u0414." to "Interact with a visible object up to 6 tiles away. 1 AP.",
        "I: \u043e\u0431\u0437\u043e\u0440 +1. II: \u0440\u0430\u0437\u0432\u0435\u0434\u043a\u0430 \u043a\u043e\u043d\u0442\u0435\u0439\u043d\u0435\u0440\u043e\u0432. III: \u0433\u043e\u0442\u043e\u0432\u0430\u044f \u043a\u0430\u0440\u0442\u0430 \u0441\u0442\u0430\u043d\u0446\u0438\u0438." to "I: vision +1. II: container intelligence. III: full station map.",
        "\u041f\u0440\u043e\u0442\u0438\u0432\u043d\u0438\u043a\u0438 \u0432\u044b\u043f\u043e\u043b\u043d\u044f\u0442 \u043e\u0431\u043e\u0437\u043d\u0430\u0447\u0435\u043d\u043d\u044b\u0435 \u0430\u0442\u0430\u043a\u0438. \u041a\u0438\u0441\u043b\u043e\u0440\u043e\u0434 \u22121, \u043e\u0442\u0440\u044f\u0434\u0443 +2 \u041e\u0414" to "Enemies execute marked attacks. Oxygen \u22121; squad AP resets to 2",
        "\u0421\u0442\u044b\u043a\u043e\u0432\u043a\u0430 \u0437\u0430\u0432\u0435\u0440\u0448\u0435\u043d\u0430. \u041a\u0438\u0441\u043b\u043e\u0440\u043e\u0434 \u0440\u0430\u0441\u0445\u043e\u0434\u0443\u0435\u0442\u0441\u044f \u043f\u043e\u0441\u043b\u0435 \u043f\u043e\u043b\u043d\u043e\u0433\u043e \u0440\u0430\u0443\u043d\u0434\u0430." to "Docking complete. Oxygen is consumed after each full round.",
        ". \u0412\u043a\u043b\u044e\u0447\u0438\u0442\u0441\u044f \u043e\u0445\u0440\u0430\u043d\u043d\u0438\u043a \u0443 \u0443\u0441\u0442\u0430\u043d\u043e\u0432\u043a\u0438, \u0431\u0435\u0437 \u043d\u0435\u043c\u0435\u0434\u043b\u0435\u043d\u043d\u043e\u0439 \u0430\u0442\u0430\u043a\u0438 \u00b7 1 \u041e\u0414" to ". Activates the nearby guardian, with no immediate attack \u00b7 1 AP",
        "4 \u0443\u0440\u043e\u043d\u0430 \u0440\u043e\u0431\u043e\u0442\u0430\u043c \u0438 \u0443\u043a\u0440\u044b\u0442\u0438\u044f\u043c \u0432 \u0440\u0430\u0434\u0438\u0443\u0441\u0435 1; \u0441\u043e\u044e\u0437\u043d\u0438\u043a\u043e\u0432 \u043d\u0435 \u0437\u0430\u0434\u0435\u0432\u0430\u0435\u0442" to "4 damage to robots and cover within radius 1; does not harm allies",
        "I: \u043a\u0438\u0441\u043b\u043e\u0440\u043e\u0434 +1. II: \u043a\u0438\u0441\u043b\u043e\u0440\u043e\u0434 +2. III: \u0434\u043e\u043f\u043e\u043b\u043d\u0438\u0442\u0435\u043b\u044c\u043d\u0430\u044f \u043a\u0430\u0441\u0441\u0435\u0442\u0430." to "I: oxygen +1. II: oxygen +2. III: extra cartridge.",
        "\u0421\u043e\u0445\u0440\u0430\u043d\u0438\u0442\u044c \u0434\u043e\u0431\u044b\u0447\u0443 \u0438 \u0432\u0435\u0440\u043d\u0443\u0442\u044c\u0441\u044f. \u0417\u0430\u0434\u0430\u043d\u0438\u0435 \u043e\u0441\u0442\u0430\u043d\u0435\u0442\u0441\u044f \u043d\u0435\u0432\u044b\u043f\u043e\u043b\u043d\u0435\u043d\u043d\u044b\u043c" to "Return with your loot. The objective will remain incomplete",
        "\u041f\u0440\u043e\u0439\u0442\u0438 \u0434\u043e 8 \u043a\u043b\u0435\u0442\u043e\u043a \u0437\u0430 1 \u041e\u0414. \u0422\u043e\u043b\u044c\u043a\u043e \u0438\u0437\u0432\u0435\u0441\u0442\u043d\u044b\u0439 \u0441\u0432\u043e\u0431\u043e\u0434\u043d\u044b\u0439 \u043f\u0443\u0442\u044c." to "Move up to 8 tiles for 1 AP along a known, clear path.",
        "\u0412\u043e\u0441\u0441\u0442\u0430\u043d\u043e\u0432\u0438\u0442\u044c 4 \u0437\u0434\u043e\u0440\u043e\u0432\u044c\u044f \u0441\u043e\u044e\u0437\u043d\u0438\u043a\u0443 \u0432 \u043f\u0440\u0435\u0434\u0435\u043b\u0430\u0445 4 \u043a\u043b\u0435\u0442\u043e\u043a. 1 \u041e\u0414." to "Restore 4 health to an ally within 4 tiles. 1 AP.",
        "\u0421\u043f\u0430\u0441\u0430\u0442\u0435\u043b\u044c\u043d\u044b\u0439 \u0434\u0440\u043e\u043d \u0432\u043e\u0437\u0432\u0440\u0430\u0449\u0430\u0435\u0442 \u043e\u0442\u0440\u044f\u0434. \u041d\u043e\u0432\u0430\u044f \u0434\u043e\u0431\u044b\u0447\u0430 \u043f\u043e\u0442\u0435\u0440\u044f\u043d\u0430." to "Rescue drone returning the squad. New loot lost.",
        "\u041b\u0451\u0433\u043a\u0438\u0439 \u043f\u0430\u0442\u0440\u0443\u043b\u044c. \u0421\u043d\u0430\u0447\u0430\u043b\u0430 \u0444\u0438\u043a\u0441\u0438\u0440\u0443\u0435\u0442 \u043a\u043b\u0435\u0442\u043a\u0443, \u0437\u0430\u0442\u0435\u043c \u0441\u0442\u0440\u0435\u043b\u044f\u0435\u0442." to "A light patrol unit. Marks a tile before firing.",
        "\u0420\u0435\u043c\u043e\u043d\u0442\u0438\u0440\u0443\u0435\u0442 \u043f\u043e\u0432\u0440\u0435\u0436\u0434\u0451\u043d\u043d\u043e\u0433\u043e \u0440\u043e\u0431\u043e\u0442\u0430 \u043f\u043e\u0431\u043b\u0438\u0437\u043e\u0441\u0442\u0438 \u0432\u043c\u0435\u0441\u0442\u043e \u0430\u0442\u0430\u043a\u0438." to "Repairs a nearby damaged robot instead of attacking.",
        "\u0412\u0440\u0435\u043c\u0435\u043d\u043d\u0430\u044f \u0434\u0430\u043b\u044c\u043d\u043e\u0441\u0442\u044c \u043e\u0440\u0443\u0436\u0438\u044f +1. \u041e\u0442\u0432\u0435\u0447\u0430\u0435\u0442 \u043d\u0430 \u0441\u0438\u0433\u043d\u0430\u043b \u0430\u0440\u0445\u0438\u0432\u0430." to "Weapon range +1 for this mission. Responds to the archive signal.",
        "\u041d\u0430 \u043e\u0431\u0448\u0438\u0432\u043a\u0435 \u043f\u0440\u043e\u0441\u0442\u0443\u043f\u0430\u044e\u0442 \u0441\u043b\u0435\u0434\u044b \u0434\u0435\u0441\u044f\u0442\u043a\u043e\u0432 \u043e\u0434\u0438\u043d\u0430\u043a\u043e\u0432\u044b\u0445 \u0440\u0435\u043c\u043e\u043d\u0442\u043e\u0432." to "The hull bears traces of dozens of identical repairs.",
        "\u041e\u0442\u043a\u043b\u044e\u0447\u0438\u0442\u044c \u0432\u0438\u0434\u0438\u043c\u043e\u0433\u043e \u0440\u043e\u0431\u043e\u0442\u0430 \u043d\u0430 \u0434\u0432\u0435 \u0444\u0430\u0437\u044b. \u0414\u0430\u043b\u044c\u043d\u043e\u0441\u0442\u044c 5; 1 \u041e\u0414." to "Disable a visible robot for two enemy phases. Range 5; 1 AP.",
        "\u0412\u043e\u0437\u0434\u0443\u0445 \u0437\u0430\u043a\u043e\u043d\u0447\u0438\u0442\u0441\u044f: \u0441\u0440\u0430\u0431\u043e\u0442\u0430\u0435\u0442 SOS, \u0434\u043e\u0431\u044b\u0447\u0430 \u0431\u0443\u0434\u0435\u0442 \u043f\u043e\u0442\u0435\u0440\u044f\u043d\u0430!" to "Oxygen will run out: SOS will activate and new loot will be lost!",
        "\u0410\u0432\u0442\u043e\u043c\u0430\u0442 \u043f\u0440\u043e\u0441\u0438\u0442 \u043f\u043e\u0434\u0442\u0432\u0435\u0440\u0434\u0438\u0442\u044c, \u0447\u0442\u043e \u043d\u0430 \u0431\u043e\u0440\u0442\u0443 \u0435\u0449\u0451 \u0435\u0441\u0442\u044c \u043b\u044e\u0434\u0438." to "An automated system asks you to confirm that humans are still aboard.",
        "\u041c\u0430\u0433\u043d\u0438\u0442\u043d\u044b\u0439 \u0437\u0430\u043c\u043e\u043a \u0437\u0430\u043a\u0440\u044b\u0442. \u0420\u044f\u0434\u043e\u043c \u043b\u0435\u0436\u0438\u0442 \u043f\u043e\u0440\u0442\u0430\u0442\u0438\u0432\u043d\u044b\u0439 \u0440\u0435\u0437\u0430\u043a." to "The magnetic lock is sealed. A portable cutter lies nearby.",
        "\u041d\u0430 \u0441\u0442\u0435\u043d\u0435 \u043c\u0435\u043b\u043e\u043c \u043d\u0430\u043d\u0435\u0441\u0451\u043d \u043c\u0430\u0440\u0448\u0440\u0443\u0442 \u043a \u0438\u0441\u0447\u0435\u0437\u043d\u0443\u0432\u0448\u0435\u043c\u0443 \u0441\u0435\u043a\u0442\u043e\u0440\u0443." to "A chalk route on the wall leads to a sector that no longer exists.",
        "\u041e\u0442\u0440\u044f\u0434 \u043d\u0435 \u043c\u043e\u0436\u0435\u0442 \u043f\u0440\u043e\u0434\u043e\u043b\u0436\u0430\u0442\u044c. \u0421\u0440\u0430\u0431\u043e\u0442\u0430\u043b \u0430\u0432\u0430\u0440\u0438\u0439\u043d\u044b\u0439 \u0432\u043e\u0437\u0432\u0440\u0430\u0442." to "Squad unable to continue. Emergency return activated.",
        "\u0411\u0440\u043e\u043d\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0439 \u0440\u043e\u0431\u043e\u0442. \u041e\u0431\u0445\u043e\u0434\u0438\u0442\u0435 \u0443\u043a\u0440\u044b\u0442\u0438\u0435 \u0438\u043b\u0438 \u043e\u0442\u043a\u043b\u044e\u0447\u0430\u0439\u0442\u0435." to "An armored robot. Flank its cover or disable it.",
        "\u0412\u0435\u0440\u043d\u0438\u0442\u0435 \u0432\u0441\u0435\u0445 \u0431\u043e\u0435\u0441\u043f\u043e\u0441\u043e\u0431\u043d\u044b\u0445 \u0438\u0441\u0441\u043b\u0435\u0434\u043e\u0432\u0430\u0442\u0435\u043b\u0435\u0439 \u0432 \u0437\u043e\u043d\u0443 \u0448\u043b\u044e\u0437\u0430" to "Bring every active explorer back to the airlock zone",
        "\u041e\u0445\u0440\u0430\u043d\u043d\u0438\u043a \u0432\u044b\u043a\u043b\u044e\u0447\u0435\u043d. \u0415\u0433\u043e \u0437\u0430\u043f\u0443\u0441\u0442\u0438\u0442 \u043a\u0438\u0441\u043b\u043e\u0440\u043e\u0434\u043d\u0430\u044f \u0443\u0441\u0442\u0430\u043d\u043e\u0432\u043a\u0430" to "Guardian offline. The oxygen station will activate it",
        "\u0421\u0438\u043b\u044c\u043d\u044b\u0439 \u043a\u043e\u0440\u043e\u0442\u043a\u0438\u0439 \u0438\u043c\u043f\u0443\u043b\u044c\u0441; \u0447\u0430\u0441\u0442\u043e \u0442\u0440\u0435\u0431\u0443\u0435\u0442 \u043f\u0435\u0440\u0435\u0437\u0430\u0440\u044f\u0434\u043a\u0438." to "A powerful short-range pulse; requires frequent reloads.",
        "\u0414\u043b\u044f \u043e\u0442\u043a\u0440\u044b\u0442\u0438\u044f \u043a\u0430\u043c\u0435\u0440\u044b \u043d\u0443\u0436\u043d\u043e \u0432\u044b\u043f\u043e\u043b\u043d\u0438\u0442\u044c \u043f\u043e\u043b\u043d\u0443\u044e \u043f\u0440\u043e\u0434\u0443\u0432\u043a\u0443." to "Opening the chamber requires a full purge.",
        "\u0412\u0440\u0435\u043c\u0435\u043d\u043d\u044b\u0439 \u0443\u0440\u043e\u043d \u043e\u0440\u0443\u0436\u0438\u044f +1. \u041d\u0435\u043e\u0431\u044b\u0447\u043d\u043e \u0442\u0451\u043f\u043b\u0430\u044f \u043d\u0430 \u043e\u0449\u0443\u043f\u044c." to "Weapon damage +1 for this mission. Strangely warm to the touch.",
        "+3 \u0449\u0438\u0442\u0430 \u0441\u0435\u0431\u0435 \u0438 \u0441\u043e\u0441\u0435\u0434\u044f\u043c. 1 \u041e\u0414; \u043f\u0435\u0440\u0435\u0437\u0430\u0440\u044f\u0434\u043a\u0430 3 \u0440\u0430\u0443\u043d\u0434\u0430." to "+3 shield to self and adjacent allies. 1 AP; 3-round cooldown.",
        "\u0412\u0440\u0435\u043c\u0435\u043d\u043d\u044b\u0439 \u043e\u0431\u0437\u043e\u0440 \u043e\u0442\u0440\u044f\u0434\u0430 +1. \u0425\u0440\u0430\u043d\u0438\u0442 \u043e\u0431\u0440\u044b\u0432\u043a\u0438 \u0433\u043e\u043b\u043e\u0441\u043e\u0432." to "Squad vision +1 for this mission. Holds fragments of voices.",
        "+3 \u0449\u0438\u0442\u0430 \u0432\u0441\u0435\u043c \u0441\u043e\u044e\u0437\u043d\u0438\u043a\u0430\u043c \u0432 \u043f\u0440\u0435\u0434\u0435\u043b\u0430\u0445 2 \u043a\u043b\u0435\u0442\u043e\u043a. 1 \u041e\u0414." to "+3 shield to all allies within 2 tiles. 1 AP.",
        "I: \u0443\u0440\u043e\u043d +1. II: \u0440\u0435\u043b\u044c\u0441\u043e\u0442\u0440\u043e\u043d. III: \u0430\u0432\u0442\u043e\u043c\u0430\u0442 \u00ab\u0421\u0438\u0433\u043c\u0430\u00bb." to "I: damage +1. II: Needle Railgun. III: Sigma Assault Rifle.",
        "\u041e\u0431\u0441\u0442\u0440\u0435\u043b\u0438\u0432\u0430\u0435\u0442 \u043e\u0442\u043c\u0435\u0447\u0435\u043d\u043d\u0443\u044e \u043a\u043b\u0435\u0442\u043a\u0443 \u0438 \u0441\u043e\u0441\u0435\u0434\u043d\u0438\u0435 \u0441 \u043d\u0435\u0439." to "Bombards the marked tile and adjacent tiles.",
        "\u0412\u0440\u0435\u043c\u0435\u043d\u043d\u043e\u0435 \u0434\u0432\u0438\u0436\u0435\u043d\u0438\u0435 +1. \u0418\u0441\u043a\u0430\u0436\u0430\u0435\u0442 \u043f\u043e\u043a\u0430\u0437\u0430\u043d\u0438\u044f \u043c\u0430\u0441\u0441\u044b." to "Movement +1 for this mission. Distorts mass readings.",
        "\u0410\u0432\u0430\u0440\u0438\u0439\u043d\u044b\u0439 \u043c\u0430\u044f\u043a \u0432\u0441\u0451 \u0435\u0449\u0451 \u043f\u043e\u0432\u0442\u043e\u0440\u044f\u0435\u0442 \u0447\u0443\u0436\u043e\u0439 \u043f\u043e\u0437\u044b\u0432\u043d\u043e\u0439." to "An emergency beacon still repeats an unfamiliar call sign.",
        "\u0412\u0440\u0435\u043c\u0435\u043d\u043d\u0430\u044f \u0431\u0440\u043e\u043d\u044f +1. \u041f\u0435\u0440\u0435\u0441\u0442\u0440\u0430\u0438\u0432\u0430\u0435\u0442\u0441\u044f \u043f\u0440\u0438 \u0443\u0434\u0430\u0440\u0435." to "Armor +1 for this mission. Reshapes itself on impact.",
        "\u0412 \u043f\u0440\u043e\u0437\u0440\u0430\u0447\u043d\u044b\u0445 \u043a\u0430\u043c\u0435\u0440\u0430\u0445 \u0440\u0430\u0441\u0442\u0443\u0442 \u0431\u043b\u0435\u0434\u043d\u044b\u0435 \u0432\u043e\u0434\u043e\u0440\u043e\u0441\u043b\u0438." to "Pale algae grow inside transparent chambers.",
        "\u0422\u0435\u0440\u043c\u0438\u043d\u0430\u043b \u0443\u0434\u0435\u0440\u0436\u0438\u0432\u0430\u0435\u0442 \u043f\u043e\u0441\u043b\u0435\u0434\u043d\u0435\u0435 \u0441\u043e\u043e\u0431\u0449\u0435\u043d\u0438\u0435 \u0434\u043e\u043c\u043e\u0439." to "A terminal holds one last message home.",
        "\u0414\u0440\u043e\u043d \u0437\u0430\u0436\u0430\u0442 \u0434\u0432\u0435\u0440\u044c\u044e, \u043d\u043e \u0435\u0433\u043e \u043f\u0430\u043c\u044f\u0442\u044c \u0435\u0449\u0451 \u0434\u043e\u0441\u0442\u0443\u043f\u043d\u0430." to "A drone is caught in a door, but its memory is still accessible.",
        "\u041e\u0434\u0438\u043d \u043c\u043e\u0449\u043d\u044b\u0439 \u0432\u044b\u0441\u0442\u0440\u0435\u043b; \u0437\u0430\u0442\u0435\u043c \u043d\u0443\u0436\u043d\u0430 \u043f\u0435\u0440\u0435\u0437\u0430\u0440\u044f\u0434\u043a\u0430." to "One powerful shot, followed by a reload.",
        "\u041d\u0435 \u0434\u0432\u0438\u0433\u0430\u0435\u0442\u0441\u044f. \u041e\u0431\u043e\u0437\u043d\u0430\u0447\u0430\u0435\u0442 \u0434\u0430\u043b\u044c\u043d\u044e\u044e \u043b\u0438\u043d\u0438\u044e \u043e\u0433\u043d\u044f." to "Stationary. Marks a long firing lane.",
        "\u0417\u0434\u043e\u0440\u043e\u0432\u044c\u0435 \u0438 \u0435\u0433\u043e \u043c\u0430\u043a\u0441\u0438\u043c\u0443\u043c +2 \u0434\u043e \u043a\u043e\u043d\u0446\u0430 \u0432\u044b\u043b\u0430\u0437\u043a\u0438." to "Current and maximum health +2 until the mission ends.",
        "\u0414\u0432\u0435 \u0446\u0435\u043b\u044b\u0435 \u043a\u0430\u0441\u0441\u0435\u0442\u044b \u0438 \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u043d\u043d\u044b\u0435 \u0431\u0430\u043b\u043b\u043e\u043d\u044b." to "Two intact cartridges sit among spent cylinders.",
        "\u0423\u0432\u0435\u043b\u0438\u0447\u0438\u0442\u044c \u043e\u0431\u0437\u043e\u0440 \u043d\u0430 4 \u0434\u043e \u0434\u0432\u0443\u0445 \u0440\u0430\u0443\u043d\u0434\u043e\u0432. 1 \u041e\u0414." to "Increase vision by 4 for two rounds. 1 AP.",
        " \u00b7 +3 \u0449\u0438\u0442\u0430 \u0441\u043e\u044e\u0437\u043d\u0438\u043a\u0430\u043c \u0432 \u0434\u0432\u0443\u0445 \u043a\u043b\u0435\u0442\u043a\u0430\u0445 \u00b7 1 \u041e\u0414" to " \u00b7 +3 shield to allies within 2 tiles \u00b7 1 AP",
        "\u0423\u0442\u0435\u0447\u043a\u0430 \u0441\u044a\u0435\u0434\u0430\u0435\u0442 \u0437\u0430\u043f\u0430\u0441 \u043c\u0435\u0441\u0442\u043d\u043e\u0433\u043e \u0440\u0435\u0437\u0435\u0440\u0432\u0443\u0430\u0440\u0430." to "A leak is draining the local reservoir.",
        "\u0411\u043b\u043e\u043a\u0438\u0440\u0443\u0435\u0442 \u043e\u0431\u0437\u043e\u0440 \u0447\u0435\u0440\u0435\u0437 \u043e\u0431\u043b\u0430\u0441\u0442\u044c \u043d\u0430 2 \u0440\u0430\u0443\u043d\u0434\u0430" to "Blocks vision through the area for 2 rounds",
        "\u041e\u0442\u043a\u043b\u044e\u0447\u0430\u0435\u0442 \u0440\u043e\u0431\u043e\u0442\u043e\u0432 \u0432 \u0440\u0430\u0434\u0438\u0443\u0441\u0435 1 \u043d\u0430 \u0434\u0432\u0435 \u0444\u0430\u0437\u044b" to "Disables robots within radius 1 for two enemy phases",
        "\u0414\u0430\u043b\u044c\u043d\u043e\u0431\u043e\u0439\u043d\u0430\u044f \u0440\u0430\u0437\u0432\u0435\u0434\u044b\u0432\u0430\u0442\u0435\u043b\u044c\u043d\u0430\u044f \u043f\u043b\u0430\u0442\u0444\u043e\u0440\u043c\u0430." to "A long-range reconnaissance weapon.",
        "\u0411\u044b\u0441\u0442\u0440\u043e \u0441\u0431\u043b\u0438\u0436\u0430\u0435\u0442\u0441\u044f \u0434\u043b\u044f \u043a\u043e\u043d\u0442\u0430\u043a\u0442\u043d\u043e\u0433\u043e \u0443\u0434\u0430\u0440\u0430." to "Closes in quickly for a melee strike.",
        "\u0412\u044b\u0431\u0435\u0440\u0438\u0442\u0435 \u0441\u0432\u043e\u0431\u043e\u0434\u043d\u044b\u0439 \u043f\u0443\u0442\u044c \u0434\u043e \u0432\u043e\u0441\u044c\u043c\u0438 \u043a\u043b\u0435\u0442\u043e\u043a" to "Select a clear path up to 8 tiles",
        "\u042d\u043b\u0438\u0442\u043d\u0430\u044f \u043c\u043e\u0431\u0438\u043b\u044c\u043d\u0430\u044f \u043f\u043b\u0430\u0442\u0444\u043e\u0440\u043c\u0430 \u0443\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0438\u044f." to "An elite mobile command platform.",
        "\u0412\u0435\u0440\u043d\u0443\u0442\u044c\u0441\u044f \u0441 \u0434\u043e\u0431\u044b\u0447\u0435\u0439 \u0438 \u0437\u0430\u0432\u0435\u0440\u0448\u0438\u0442\u044c \u0437\u0430\u0434\u0430\u043d\u0438\u0435" to "Return with loot and complete the mission",
        "\u0412\u044b\u0431\u0435\u0440\u0438\u0442\u0435 \u0432\u0438\u0434\u0438\u043c\u043e\u0433\u043e \u0440\u043e\u0431\u043e\u0442\u0430 \u0432 \u043f\u044f\u0442\u0438 \u043a\u043b\u0435\u0442\u043a\u0430\u0445" to "Select a visible robot within 5 tiles",
        "\u041d\u0435\u0442 \u043b\u0438\u043d\u0438\u0438 \u043e\u0433\u043d\u044f \u0438\u043b\u0438 \u0446\u0435\u043b\u044c \u0441\u043b\u0438\u0448\u043a\u043e\u043c \u0434\u0430\u043b\u0435\u043a\u043e" to "No line of fire, or target out of range",
        " \u00b7 \u043e\u0442\u043a\u043b\u044e\u0447\u0435\u043d\u0438\u0435 \u043d\u0430 \u0434\u0432\u0435 \u0444\u0430\u0437\u044b \u0432\u0440\u0430\u0433\u0430 \u00b7 1 \u041e\u0414" to " \u00b7 disable for two enemy phases \u00b7 1 AP",
        "\u00bb. +2 \u0434\u0430\u043d\u043d\u044b\u0445 \u0438 \u0441\u0435\u0440\u0432\u0438\u0441\u043d\u044b\u0439 \u043f\u0440\u043e\u0445\u043e\u0434 \u00b7 1 \u041e\u0414" to ". +2 data and a service passage \u00b7 1 AP",
        "\u0411\u043e\u043b\u044c\u0448\u043e\u0439 \u043c\u0430\u0433\u0430\u0437\u0438\u043d \u0434\u043b\u044f \u043f\u043e\u0434\u0434\u0435\u0440\u0436\u043a\u0438 \u043e\u0442\u0440\u044f\u0434\u0430." to "A large magazine for sustained squad support.",
        "\u041e\u0434\u043d\u043e\u043a\u0440\u0430\u0442\u043d\u043e \u0434\u0430\u0451\u0442 \u043a\u0430\u0436\u0434\u043e\u043c\u0443 \u0431\u043e\u0439\u0446\u0443 \u0449\u0438\u0442 +3." to "Grants each squad member a one-time shield of +3.",
        "\u0428\u043b\u044e\u0437 \u0437\u0430\u043a\u0440\u044b\u0442. \u041e\u0442\u0440\u044f\u0434 \u0438 \u0434\u043e\u0431\u044b\u0447\u0430 \u043d\u0430 \u0431\u043e\u0440\u0442\u0443." to "Airlock sealed. Squad and loot aboard.",
        "\u041d\u0430\u0434\u0451\u0436\u043d\u044b\u0439 \u043a\u0430\u0440\u0430\u0431\u0438\u043d \u0434\u043b\u044f \u043e\u0431\u0445\u043e\u0434\u0430 \u0443\u043a\u0440\u044b\u0442\u0438\u0439." to "A reliable carbine for flanking cover.",
        "\u042d\u043b\u0438\u0442\u043d\u044b\u0439 \u043e\u0445\u0440\u0430\u043d\u043d\u0438\u043a \u0441 \u0443\u0441\u0438\u043b\u0435\u043d\u043d\u043e\u0439 \u0431\u0440\u043e\u043d\u0451\u0439." to "An elite guardian with reinforced armor.",
        "\u0412\u044b\u0431\u0435\u0440\u0438\u0442\u0435 \u0432\u0438\u0434\u0438\u043c\u043e\u0433\u043e \u0440\u043e\u0431\u043e\u0442\u0430 \u0438\u043b\u0438 \u0443\u043a\u0440\u044b\u0442\u0438\u0435" to "Select a visible robot or cover",
        "\u0412\u044b\u0431\u0435\u0440\u0438\u0442\u0435 \u0432\u0438\u0434\u0438\u043c\u0443\u044e \u043a\u043b\u0435\u0442\u043a\u0443 \u0432 \u043f\u044f\u0442\u0438 \u0448\u0430\u0433\u0430\u0445" to "Select a visible tile within 5 tiles",
        "\u0410\u0440\u0445\u0438\u0432 \u0437\u0430\u0431\u043b\u043e\u043a\u0438\u0440\u043e\u0432\u0430\u043d. \u041e\u0442\u043a\u043b\u044e\u0447\u0438\u0442\u0435 \u0421\u0442\u0440\u0430\u0436\u0430" to "Archive locked. Disable the Warden",
        "\u0414\u043b\u044f \u0432\u044b\u0441\u0430\u0434\u043a\u0438 \u043d\u0443\u0436\u043d\u044b \u0442\u0440\u0438 \u0438\u0441\u0441\u043b\u0435\u0434\u043e\u0432\u0430\u0442\u0435\u043b\u044f" to "Three explorers are required to deploy",
        "\u0412\u044b\u0431\u0435\u0440\u0438\u0442\u0435 \u0441\u043e\u044e\u0437\u043d\u0438\u043a\u0430 \u0432 \u0447\u0435\u0442\u044b\u0440\u0451\u0445 \u043a\u043b\u0435\u0442\u043a\u0430\u0445" to "Select an ally within 4 tiles",
        "\u041e\u0431\u044a\u0435\u043a\u0442 \u0443\u0436\u0435 \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u043d \u0438\u043b\u0438 \u043d\u0435 \u0432\u0438\u0434\u0435\u043d" to "Object already used or not visible",
        "\u0421\u043d\u0430\u0447\u0430\u043b\u0430 \u043e\u0441\u0432\u043e\u0431\u043e\u0434\u0438\u0442\u0435 \u043e\u0431\u044a\u0435\u043a\u0442 \u043e\u0442 \u043e\u0445\u0440\u0430\u043d\u044b" to "Clear the guardian from the object first",
        "\u0414\u043b\u0438\u0442\u0435\u043b\u044c\u043d\u0430\u044f \u0440\u0430\u0431\u043e\u0442\u0430 \u0431\u0435\u0437 \u043f\u0435\u0440\u0435\u0437\u0430\u0440\u044f\u0434\u043a\u0438." to "Sustained fire with fewer reloads.",
        "\u0412\u0440\u0435\u043c\u0435\u043d\u043d\u0430\u044f \u0432\u043c\u0435\u0441\u0442\u0438\u043c\u043e\u0441\u0442\u044c \u043c\u0430\u0433\u0430\u0437\u0438\u043d\u0430 +2." to "Magazine capacity +2 for this mission.",
        "\u041d\u0443\u0436\u0435\u043d \u0432\u0438\u0434\u0438\u043c\u044b\u0439 \u0440\u043e\u0431\u043e\u0442 \u0432 \u0434\u0432\u0443\u0445 \u043a\u043b\u0435\u0442\u043a\u0430\u0445" to "Requires a visible robot within 2 tiles",
        "\u0421\u0442\u0440\u0430\u0436 \u0432 \u0430\u0432\u0430\u0440\u0438\u0439\u043d\u043e\u043c \u0440\u0435\u0436\u0438\u043c\u0435: \u0443\u0440\u043e\u043d +1." to "Warden emergency mode: damage +1.",
        "\u041e\u0431\u0437\u043e\u0440 \u0432\u0441\u0435\u0433\u043e \u043e\u0442\u0440\u044f\u0434\u0430 +4 \u043d\u0430 2 \u0440\u0430\u0443\u043d\u0434\u0430" to "Squad vision +4 for 2 rounds",
        " \u00b7 \u043e\u0431\u0437\u043e\u0440 +4 \u043d\u0430 \u0434\u0432\u0430 \u0440\u0430\u0443\u043d\u0434\u0430 \u00b7 1 \u041e\u0414" to " \u00b7 vision +4 for two rounds \u00b7 1 AP",
        "\u0412\u044b\u0431\u0435\u0440\u0438\u0442\u0435 \u0440\u0430\u043d\u0435\u043d\u043e\u0433\u043e \u0441\u043e\u044e\u0437\u043d\u0438\u043a\u0430 \u0440\u044f\u0434\u043e\u043c" to "Select an adjacent injured ally",
        "\u0421\u043d\u0430\u0447\u0430\u043b\u0430 \u043e\u0431\u043d\u0430\u0440\u0443\u0436\u044c\u0442\u0435 \u044d\u0442\u043e\u0442 \u0443\u0447\u0430\u0441\u0442\u043e\u043a" to "Explore this area first",
        " \u00b7 \u0412\u041d\u0418\u041c\u0410\u041d\u0418\u0415: \u0430\u0432\u0430\u0440\u0438\u0439\u043d\u044b\u0439 \u0432\u043e\u0437\u0432\u0440\u0430\u0442!" to " \u00b7 WARNING: emergency return!",
        "\u0424\u0440\u0430\u0433\u043c\u0435\u043d\u0442\u044b \u043d\u0430\u0432\u0438\u0433\u0430\u0446\u0438\u043e\u043d\u043d\u043e\u0433\u043e \u0430\u0440\u0445\u0438\u0432\u0430" to "Navigation archive fragments",
        "\u0417\u0434\u043e\u0440\u043e\u0432\u044c\u0435 \u0441\u043e\u0441\u0435\u0434\u043d\u0435\u0433\u043e \u0441\u043e\u044e\u0437\u043d\u0438\u043a\u0430 +4" to "Adjacent ally health +4",
        " \u00b7 +3 \u0449\u0438\u0442\u0430 \u043e\u0442\u0440\u044f\u0434\u0443 \u0440\u044f\u0434\u043e\u043c \u00b7 1 \u041e\u0414" to " \u00b7 +3 shield to nearby squad members \u00b7 1 AP",
        " \u00b7 \u043e\u0442\u043a\u043b\u044e\u0447\u0438\u0442 \u043e\u0445\u0440\u0430\u043d\u0443 \u043d\u0430 \u0434\u0432\u0435 \u0444\u0430\u0437\u044b" to " \u00b7 disables security for two enemy phases",
        "\u041e\u0442\u043a\u0440\u044b\u0442\u044c \u0441\u0435\u0440\u0432\u0438\u0441\u043d\u0443\u044e \u0434\u0432\u0435\u0440\u044c \u00b7 1 \u041e\u0414" to "Open service door \u00b7 1 AP",
        "\u0417\u0430\u0449\u0438\u0449\u0451\u043d\u043d\u044b\u0439 \u0433\u0440\u0443\u0437\u043e\u0432\u043e\u0439 \u043a\u043e\u043d\u0442\u0435\u0439\u043d\u0435\u0440" to "Secured cargo container",
        " \u0443\u0440\u043e\u043d\u0430 \u0438 \u043e\u0442\u0431\u0440\u0430\u0441\u044b\u0432\u0430\u043d\u0438\u0435 \u00b7 2 \u041e\u0414" to " damage and knockback \u00b7 2 AP",
        "\u0417\u0430\u043f\u0430\u0441\u043d\u044b\u0435 \u043a\u0438\u0441\u043b\u043e\u0440\u043e\u0434\u043d\u044b\u0435 \u043a\u0430\u0441\u0441\u0435\u0442\u044b" to "Spare oxygen cartridges",
        "\u041e\u0448\u0438\u0431\u043a\u0430 \u0440\u0435\u0437\u0435\u0440\u0432\u043d\u043e\u0439 \u043f\u043b\u0430\u043d\u0438\u0440\u043e\u0432\u043a\u0438" to "Invalid fallback layout",
        "\u0412\u0441\u043a\u0440\u044b\u0442\u044c \u0441 \u0437\u0430\u0442\u0440\u0430\u0442\u043e\u0439 \u0432\u043e\u0437\u0434\u0443\u0445\u0430" to "Cut it open using oxygen",
        "\u0417\u0430\u0431\u0440\u0430\u0442\u044c \u043d\u0430\u0432\u0438\u0433\u0430\u0446\u0438\u043e\u043d\u043d\u044b\u0439 \u0431\u043b\u043e\u043a" to "Take the navigation unit",
        "\u0412\u044b\u043d\u043e\u0441\u043b\u0438\u0432\u043e\u0441\u0442\u044c \u00b7 \u0437\u0434\u043e\u0440\u043e\u0432\u044c\u0435 +2" to "Endurance \u00b7 health +2",
        "\u0418\u0421\u0421\u041b\u0415\u0414\u041e\u0412\u0410\u0422\u0415\u041b\u042c\u0421\u041a\u0418\u0419 \u041a\u041e\u041c\u041f\u041b\u0415\u041a\u0421" to "RESEARCH COMPLEX",
        "\u041e\u0431\u044a\u0435\u043a\u0442 \u0437\u0430\u043a\u0440\u044b\u0442 \u043f\u0435\u0440\u0435\u0433\u043e\u0440\u043e\u0434\u043a\u043e\u0439" to "A partition blocks the object",
        "\u041c\u0430\u043a\u0441\u0438\u043c\u0430\u043b\u044c\u043d\u043e\u0435 \u0437\u0434\u043e\u0440\u043e\u0432\u044c\u0435 +2." to "Maximum health +2.",
        "\u041c\u0430\u043a\u0441\u0438\u043c\u0430\u043b\u044c\u043d\u043e\u0435 \u0437\u0434\u043e\u0440\u043e\u0432\u044c\u0435 +4." to "Maximum health +4.",
        "\u042d\u0442\u043e\u0442 \u0440\u0430\u0441\u0445\u043e\u0434\u043d\u0438\u043a \u0437\u0430\u043a\u043e\u043d\u0447\u0438\u043b\u0441\u044f" to "This supply is depleted",
        "\u041f\u043e\u0434\u043e\u0439\u0434\u0438\u0442\u0435 \u043a \u043e\u0431\u044a\u0435\u043a\u0442\u0443 \u0431\u043b\u0438\u0436\u0435" to "Move closer to the object",
        "\u0413\u0435\u0440\u043c\u0435\u0442\u0438\u0447\u043d\u044b\u0439 \u043f\u043e\u0434\u0434\u043e\u0441\u043f\u0435\u0448\u043d\u0438\u043a" to "Sealed Undersuit",
        "\u0423\u0441\u043a\u043e\u0440\u0438\u0442\u0435\u043b\u044c \u0441\u0435\u0440\u0432\u043e\u043f\u0440\u0438\u0432\u043e\u0434\u043e\u0432" to "Servo Booster",
        "\u0412\u043c\u0435\u0441\u0442\u0438\u043c\u043e\u0441\u0442\u044c \u043c\u0430\u0433\u0430\u0437\u0438\u043d\u0430 +2." to "Magazine capacity +2.",
        "\u041c\u0438\u043a\u0440\u043e\u0431\u0438\u043e\u043b\u043e\u0433\u0438\u0447\u0435\u0441\u043a\u0438\u0439 \u043e\u0442\u0441\u0435\u043a" to "Microbiology Bay",
        "\u0412\u044b\u0431\u0435\u0440\u0438\u0442\u0435 \u0432\u0430\u0440\u0438\u0430\u043d\u0442 \u0441\u043e\u0431\u044b\u0442\u0438\u044f" to "Choose an event option",
        "\u041e\u0442\u043a\u043b\u044e\u0447\u0438\u0442\u044c \u0437\u0430\u0449\u0438\u0442\u043d\u044b\u0439 \u0443\u0437\u0435\u043b" to "Disable the defense node",
        "\u041d\u0435\u0438\u0437\u0432\u0435\u0441\u0442\u043d\u0430\u044f \u0441\u043f\u043e\u0441\u043e\u0431\u043d\u043e\u0441\u0442\u044c" to "Unknown ability",
        "\u0414\u0430\u043b\u044c\u043d\u043e\u0441\u0442\u044c \u0434\u0432\u0438\u0436\u0435\u043d\u0438\u044f +1." to "Movement range +1.",
        "\u0422\u0435\u043b\u0435\u043c\u0435\u0442\u0440\u0438\u0447\u0435\u0441\u043a\u0438\u0439 \u043f\u0440\u0438\u0446\u0435\u043b" to "Telemetry Sight",
        "\u041e\u0442\u043a\u043b\u044e\u0447\u0438\u0442\u044c \u0440\u0435\u0442\u0440\u0430\u043d\u0441\u043b\u044f\u0442\u043e\u0440" to "Disable the relay",
        "\u0412\u044b\u0431\u0435\u0440\u0438\u0442\u0435 \u0438\u0441\u0441\u043b\u0435\u0434\u043e\u0432\u0430\u0442\u0435\u043b\u044f" to "Select an explorer",
        "\u0417\u0434\u0435\u0441\u044c \u043d\u0435\u0442 \u043e\u0431\u043e\u0440\u0443\u0434\u043e\u0432\u0430\u043d\u0438\u044f" to "No equipment here",
        "\u0421\u043a\u043b\u0430\u0434\u0447\u0430\u0442\u044b\u0439 \u043d\u0430\u043a\u043e\u043f\u0438\u0442\u0435\u043b\u044c" to "Folded Accumulator",
        "\u041f\u043e\u0434\u043a\u043b\u044e\u0447\u0438\u0442\u044c \u043a\u043e\u043c\u043f\u0440\u0435\u0441\u0441\u043e\u0440" to "Connect the compressor",
        "\u041d\u0435\u043e\u0442\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u043d\u043e\u0435 \u043f\u0438\u0441\u044c\u043c\u043e" to "Unsent Letter",
        "\u0412\u043e\u0441\u0441\u0442\u0430\u043d\u043e\u0432\u0438\u0442\u044c \u0430\u0434\u0440\u0435\u0441\u0430\u0442\u0430" to "Recover the recipient",
        "\u0421\u0442\u044b\u043a\u043e\u0432\u043e\u0447\u043d\u0430\u044f \u043f\u043b\u0430\u0442\u0444\u043e\u0440\u043c\u0430" to "Docking Platform",
        "\u0417\u0430\u043a\u0430\u043b\u043a\u0430 \u00b7 \u0437\u0434\u043e\u0440\u043e\u0432\u044c\u0435 +2" to "Tempered \u00b7 health +2",
        "\u0418\u043c\u043f\u043b\u0430\u043d\u0442 \u00b7 \u0437\u0434\u043e\u0440\u043e\u0432\u044c\u0435 +2" to "Implant \u00b7 health +2",
        "\u041f\u043e\u043b\u043d\u044b\u0439 \u043c\u0430\u0433\u0430\u0437\u0438\u043d \u00b7 1 \u041e\u0414" to "Refill magazine \u00b7 1 AP",
        "\u041a\u0438\u0441\u043b\u043e\u0440\u043e\u0434 \u0443\u0436\u0435 \u0437\u0430\u043f\u043e\u043b\u043d\u0435\u043d" to "Oxygen already full",
        "\u0417\u0430\u0431\u0440\u0430\u0442\u044c \u043a\u043e\u043d\u0442\u0435\u0439\u043d\u0435\u0440 \u0438 \u00ab" to "Collect container and ",
        " \u00b7 \u0434\u0432\u0438\u0436\u0435\u043d\u0438\u0435 \u043e\u0442\u0440\u044f\u0434\u0430 \u22121" to " \u00b7 squad movement \u22121",
        "\u041a\u0435\u0440\u0430\u043c\u0438\u0447\u0435\u0441\u043a\u0438\u0439 \u0432\u043a\u043b\u0430\u0434\u044b\u0448" to "Ceramic Insert",
        "\u0423\u0441\u0438\u043b\u0435\u043d\u043d\u044b\u0439 \u044d\u043a\u0437\u043e\u043a\u0430\u0440\u043a\u0430\u0441" to "Reinforced Exoframe",
        "\u041e\u043f\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0439 \u0434\u0430\u043b\u044c\u043d\u043e\u043c\u0435\u0440" to "Optical Rangefinder",
        "\u0414\u0430\u043b\u044c\u043d\u043e\u0441\u0442\u044c \u043e\u0440\u0443\u0436\u0438\u044f +1." to "Weapon range +1.",
        "\u0414\u0430\u043b\u044c\u043d\u043e\u0441\u0442\u044c \u043e\u0440\u0443\u0436\u0438\u044f +2." to "Weapon range +2.",
        "\u041f\u043e\u0434\u043a\u043b\u044e\u0447\u0438\u0442\u044c \u0431\u0438\u043e\u0444\u0438\u043b\u044c\u0442\u0440" to "Connect the biofilter",
        "\u041a\u043e\u043d\u0442\u0435\u0439\u043d\u0435\u0440\u043d\u0430\u044f \u0433\u0430\u043b\u0435\u0440\u0435\u044f" to "Container Gallery",
        "\u041f\u0435\u0440\u0435\u0433\u0440\u0443\u0437\u043e\u0447\u043d\u0430\u044f \u043a\u0430\u043c\u0435\u0440\u0430" to "Transfer Chamber",
        "\u041f\u0440\u0438\u0451\u043c\u043d\u0430\u044f \u043b\u0430\u0431\u043e\u0440\u0430\u0442\u043e\u0440\u0438\u044f" to "Intake Laboratory",
        "\u041a\u0440\u0438\u043e\u0433\u0435\u043d\u043d\u043e\u0435 \u0445\u0440\u0430\u043d\u0438\u043b\u0438\u0449\u0435" to "Cryogenic Storage",
        "\u0420\u0435\u0437\u0435\u0440\u0432 \u00b7 \u0437\u0434\u043e\u0440\u043e\u0432\u044c\u0435 +2" to "Reserve \u00b7 health +2",
        "\u041f\u0435\u0440\u0435\u0433\u0440\u0443\u0437\u043a\u0430 \u00b7 \u0443\u0440\u043e\u043d +1" to "Overload \u00b7 damage +1",
        "\u0420\u0430\u0441\u0448\u0438\u0440\u0435\u043d\u043d\u044b\u0439 \u043c\u0430\u0433\u0430\u0437\u0438\u043d" to "Extended Magazine",
        "\u041d\u0443\u043b\u0435\u0432\u043e\u0439 \u043a\u043e\u043d\u0434\u0435\u043d\u0441\u0430\u0442\u043e\u0440" to "Zero Capacitor",
        "\u041f\u043e\u0441\u043b\u0435\u0434\u043d\u0438\u0439 \u043a\u043e\u043d\u0442\u0435\u0439\u043d\u0435\u0440" to "The Last Container",
        "\u0421\u043f\u0435\u043a\u0442\u0440\u0430\u043b\u044c\u043d\u0430\u044f \u043a\u0430\u043c\u0435\u0440\u0430" to "Spectral Chamber",
        "\u041a\u0438\u0441\u043b\u043e\u0440\u043e\u0434\u043d\u0430\u044f \u043a\u0430\u0441\u0441\u0435\u0442\u0430" to "Oxygen Cartridge",
        "\u041d\u0435\u0442 \u0441\u0432\u043e\u0431\u043e\u0434\u043d\u043e\u0433\u043e \u043f\u0443\u0442\u0438" to "No clear path",
        "\u041d\u0435\u0438\u0437\u0432\u0435\u0441\u0442\u043d\u0430\u044f \u043a\u043e\u043c\u0430\u043d\u0434\u0430" to "Unknown command",
        "\u0420\u0435\u0430\u043a\u0442\u0438\u0432\u043d\u0430\u044f \u043e\u0431\u0448\u0438\u0432\u043a\u0430" to "Reactive Plating",
        "\u041a\u043e\u043c\u043f\u043e\u0437\u0438\u0442 \u00ab\u0411\u0430\u0441\u0442\u0438\u043e\u043d\u00bb" to "Bastion Composite",
        "\u0424\u043e\u043a\u0443\u0441\u0438\u0440\u0443\u044e\u0449\u0430\u044f \u043b\u0438\u043d\u0437\u0430" to "Focusing Lens",
        "\u0412\u043e\u0441\u0441\u0442\u0430\u043d\u043e\u0432\u0438\u0442\u044c \u043a\u0430\u0440\u0442\u0443" to "Reconstruct the map",
        "\u041f\u0435\u0440\u0435\u0434\u0430\u0442\u044c \u0431\u0438\u043e\u043c\u0435\u0442\u0440\u0438\u044e" to "Transmit biometrics",
        "\u041f\u043e\u0434\u043a\u043b\u044e\u0447\u0438\u0442\u044c \u043a\u0430\u0441\u0441\u0435\u0442\u044b" to "Connect the cartridges",
        "\u041e\u0441\u0442\u0430\u0442\u043e\u0447\u043d\u043e\u0435 \u0434\u044b\u0445\u0430\u043d\u0438\u0435" to "Residual Breath",
        "\u041a\u043e\u043c\u043c\u0443\u0442\u0430\u0446\u0438\u043e\u043d\u043d\u044b\u0439 \u0437\u0430\u043b" to "Switching Hall",
        "\u041d\u0430\u0432\u0438\u0433\u0430\u0446\u0438\u043e\u043d\u043d\u044b\u0439 \u0443\u0437\u0435\u043b" to "Navigation Hub",
        "\u0422\u043e\u0447\u043d\u043e\u0441\u0442\u044c \u00b7 \u0443\u0440\u043e\u043d +1" to "Precision \u00b7 damage +1",
        "\u0418\u043c\u043f\u0443\u043b\u044c\u0441\u043d\u0430\u044f \u0433\u0440\u0430\u043d\u0430\u0442\u0430" to "Pulse Grenade",
        "\u0411\u043e\u0435\u0446 \u043d\u0435\u0434\u0435\u0435\u0441\u043f\u043e\u0441\u043e\u0431\u0435\u043d" to "Explorer incapacitated",
        " \u0443\u0440\u043e\u043d\u0430 \u00b7 \u0443\u043a\u0440\u044b\u0442\u0438\u0435 \u2212" to " damage \u00b7 cover \u2212",
        "\u041d\u0435\u0442 \u0432\u0437\u0430\u0438\u043c\u043e\u0434\u0435\u0439\u0441\u0442\u0432\u0438\u044f" to "No interaction available",
        "\u0412\u0438\u043d\u0442\u043e\u0432\u043a\u0430 \u00ab\u041f\u0440\u0435\u0434\u0435\u043b\u00bb" to "Horizon Rifle",
        "\u0420\u0435\u043b\u044c\u0441\u043e\u0442\u0440\u043e\u043d \u00ab\u0418\u0433\u043b\u0430\u00bb" to "Needle Railgun",
        "\u041d\u0430\u0447\u0430\u043b\u044c\u043d\u044b\u0439 \u0449\u0438\u0442 +3." to "Starting shield +3.",
        "\u0420\u0430\u0434\u0438\u0443\u0441 \u043e\u0431\u0437\u043e\u0440\u0430 +2." to "Vision radius +2.",
        "\u0422\u0440\u0435\u0449\u0438\u043d\u0430 \u0432 \u043a\u043e\u043d\u0442\u0443\u0440\u0435" to "Fractured Loop",
        "\u0417\u0430\u0431\u0440\u0430\u0442\u044c \u043a\u0440\u0435\u043f\u043b\u0435\u043d\u0438\u044f" to "Take the fittings",
        "\u0413\u0440\u0443\u0437\u043e\u0432\u043e\u0439 \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u044c" to "Cargo Control",
        "\u0421\u043d\u0430\u0439\u043f\u0435\u0440 \u00b7 \u0443\u0440\u043e\u043d +1" to "Sharpshooter \u00b7 damage +1",
        "\u0412\u043e\u0441\u0441\u0442\u0430\u043d\u043e\u0432\u0438\u0442\u044c \u0443\u0437\u0435\u043b" to "Restore the node",
        "\u0422\u0420\u0410\u041d\u0421\u041f\u041e\u0420\u0422\u041d\u042b\u0419 \u0423\u0417\u0415\u041b" to "TRANSPORT HUB",
        "\u0412\u044b\u043b\u0430\u0437\u043a\u0430 \u0437\u0430\u0432\u0435\u0440\u0448\u0435\u043d\u0430" to "Mission complete",
        "\u041d\u0443\u0436\u043d\u0430 \u043f\u0435\u0440\u0435\u0437\u0430\u0440\u044f\u0434\u043a\u0430" to "Reload required",
        "\u041c\u0430\u0433\u0430\u0437\u0438\u043d \u0443\u0436\u0435 \u043f\u043e\u043b\u043e\u043d" to "Magazine already full",
        "\u041a\u0430\u0440\u0430\u0431\u0438\u043d \u00ab\u0412\u0435\u043a\u0442\u043e\u0440\u00bb" to "Vector Carbine",
        "\u0418\u043c\u043f\u0443\u043b\u044c\u0441\u043d\u044b\u0439 \u0440\u0435\u0437\u0430\u043a" to "Pulse Cutter",
        "\u041f\u0438\u0441\u0442\u043e\u043b\u0435\u0442 \u00ab\u0428\u0442\u0438\u043b\u044c\u00bb" to "Stillwater Pistol",
        "\u0421\u043e\u0445\u0440\u0430\u043d\u0438\u0442\u044c \u0437\u0430\u043f\u0438\u0441\u044c" to "Save the recording",
        "\u041f\u0435\u0440\u0435\u043a\u0440\u044b\u0442\u044c \u043a\u043e\u043d\u0442\u0443\u0440" to "Seal the loop",
        "\u0420\u0430\u0437\u043e\u0431\u0440\u0430\u0442\u044c \u043a\u043b\u0430\u043f\u0430\u043d" to "Salvage the valve",
        "\u0418\u0441\u0441\u043b\u0435\u0434\u043e\u0432\u0430\u0442\u044c \u0441\u043b\u043e\u0438" to "Study the layers",
        "\u0412\u044b\u0440\u0435\u0437\u0430\u0442\u044c \u043e\u0431\u0440\u0430\u0437\u0435\u0446" to "Cut out a sample",
        "\u0420\u0430\u0431\u043e\u0447\u0430\u044f \u0433\u0438\u043f\u043e\u0442\u0435\u0437\u0430" to "Working Hypothesis",
        "\u041e\u0442\u043c\u0435\u043d\u0430 \u044d\u0432\u0430\u043a\u0443\u0430\u0446\u0438\u0438" to "Evacuation Canceled",
        "\u041f\u043e\u0441\u043b\u0435\u0434\u043d\u0438\u0439 \u043f\u0440\u0438\u043a\u0430\u0437" to "Final Order",
        "\u041f\u043e\u0433\u0440\u0443\u0437\u043e\u0447\u043d\u044b\u0439 \u0443\u0437\u0435\u043b" to "Loading Hub",
        "\u041a\u0430\u0440\u0430\u043d\u0442\u0438\u043d\u043d\u044b\u0439 \u0448\u043b\u044e\u0437" to "Quarantine Airlock",
        "\u0421\u0438\u043b\u043e\u0432\u0430\u044f \u0440\u0430\u0437\u0432\u044f\u0437\u043a\u0430" to "Power Junction",
        "\u041a\u0430\u043c\u0435\u0440\u0430 \u043f\u0440\u043e\u0442\u043e\u043a\u043e\u043b\u0430" to "Protocol Chamber",
        "\u0423\u0414\u0410\u041b\u0401\u041d\u041d\u042b\u0419 \u0414\u041e\u0421\u0422\u0423\u041f" to "REMOTE ACCESS",
        "\u0421\u0438\u0433\u043d\u0430\u043b\u044c\u043d\u0430\u044f \u0441\u0444\u0435\u0440\u0430" to "Signal Orb",
        "\u0416\u0418\u0417\u041d\u0415\u041e\u0411\u0415\u0421\u041f\u0415\u0427\u0415\u041d\u0418\u0415" to "LIFE SUPPORT",
